package com.sports.payment_service.controller; import com.sports.payment_service.dto.request.InitializePaymentRequest; import com.sports.payment_service.dto.response.*; import com.sports.payment_service.entity.PaymentStatus; import com.sports.payment_service.security.AuthenticatedUser; import com.sports.payment_service.service.PaymentService; import lombok.RequiredArgsConstructor; import org.springframework.http.*; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*; import java.util.List; @RestController @RequestMapping("/api/payments") @RequiredArgsConstructor public class PaymentController { private final PaymentService s; private AuthenticatedUser u(Authentication a){return (AuthenticatedUser)a.getPrincipal();} @PostMapping("/initialize") @PreAuthorize("hasRole('COACH')") ResponseEntity<InitializePaymentResponse> init(@RequestBody(required=false) InitializePaymentRequest r,Authentication a){var u=u(a);return ResponseEntity.status(HttpStatus.CREATED).body(s.initialize(u.userId(),u.email(),r));} @GetMapping("/verify/{reference}") @PreAuthorize("hasRole('COACH')") PaymentResponse verify(@PathVariable String reference,Authentication a){return s.verify(u(a).userId(),reference);} @GetMapping("/me") @PreAuthorize("hasRole('COACH')") List<PaymentResponse> me(Authentication a){return s.mine(u(a).userId());} @GetMapping("/subscription/me") @PreAuthorize("hasRole('COACH')") SubscriptionStatusResponse sub(Authentication a){return s.sub(u(a).userId());} @GetMapping @PreAuthorize("hasRole('ADMIN')") List<PaymentResponse> all(@RequestParam(required=false) PaymentStatus status,@RequestParam(required=false) Long coachId){return s.all(status,coachId);} @GetMapping("/coach/{coachId}") @PreAuthorize("hasRole('ADMIN')") List<PaymentResponse> coach(@PathVariable Long coachId){return s.mine(coachId);} @GetMapping("/subscription/coach/{coachId}") @PreAuthorize("hasRole('ADMIN')") SubscriptionStatusResponse coachSub(@PathVariable Long coachId){return s.sub(coachId);} @PostMapping("/webhook") ResponseEntity<Void> webhook(@RequestBody String body,@RequestHeader(value="x-paystack-signature",required=false)String sig){s.webhook(body,sig);return ResponseEntity.ok().build();} }